mutation SetFields($projectId: ID!, $itemId: ID!, $f0Field: ID!, $f0Value: String!, $f1Field: ID!, $f1Value: String!) {
  f0: updateProjectV2ItemFieldValue(input: { projectId: $projectId, itemId: $itemId, fieldId: $f0Field, value: { text: $f0Value } }) { clientMutationId }
  f1: updateProjectV2ItemFieldValue(input: { projectId: $projectId, itemId: $itemId, fieldId: $f1Field, value: { singleSelectOptionId: $f1Value } }) { clientMutationId }
}

